import { describe, it, expect, beforeEach } from "vitest";
import { AppConfig } from "./app-config";
import { listOrders, Order } from "./orders";

describe("listOrders with legacy mode", () => {
  beforeEach(() => {
    AppConfig.legacyOrderIds = true;
  });

  it("returns the orders", () => {
    const rows: Order[] = listOrders();
    expect(rows.length).toBeGreaterThan(0);
  });
});

describe("listOrders default mode", () => {
  it("returns numeric order ids", () => {
    expect(listOrders()[0].id).toMatch(/^\d+$/);
  });
});
